<?php
namespace App\Services\Accounting;
use App\Models\{Folio,FolioItem,HotelBusinessDate,NightAudit,Payment,PosOrder,Reservation,Room,Stay};use App\Services\Folios\FolioService;use Illuminate\Support\Facades\DB;use RuntimeException;
class NightAuditService{
 public function __construct(private FolioService $folios){}
 public function currentDate(int $propertyId):HotelBusinessDate{return HotelBusinessDate::firstOrCreate(['property_id'=>$propertyId,'business_date'=>now()->toDateString()],['status'=>'open','opened_at'=>now()]);}
 public function run(int $propertyId,int $userId):NightAudit{return DB::transaction(function()use($propertyId,$userId){$bd=$this->currentDate($propertyId);if($bd->status==='closed')throw new RuntimeException('This hotel business date is already closed.');$bd->update(['status'=>'closing']);$date=$bd->business_date->toDateString();$exceptions=[];$inHouse=Stay::with(['reservation','room'])->where('property_id',$propertyId)->where('status','in_house')->get();foreach($inHouse as $stay){$folio=Folio::where('stay_id',$stay->id)->orWhere('reservation_id',$stay->reservation_id)->first();if(!$folio&&$stay->reservation)$folio=$this->folios->ensureForReservation($stay->reservation,$stay);if($folio&&$stay->room){$exists=FolioItem::where('folio_id',$folio->id)->where('department','room')->whereDate('posted_at',$date)->exists();if(!$exists){$rate=(float)($stay->reservation?->rooms?->first()?->rate_amount??$stay->room?->roomType?->base_rate??0);if($rate>0)$this->folios->addCharge($folio,['department'=>'room','description'=>'Night audit room charge - '.$stay->room->room_number,'quantity'=>1,'unit_price'=>$rate,'tax_amount'=>0],$userId);else $exceptions[]='No room rate found for stay #'.$stay->id;}}}
 $audit=NightAudit::updateOrCreate(['property_id'=>$propertyId,'business_date'=>$date],['status'=>'running','run_by'=>$userId,'started_at'=>now()]);$roomRevenue=(float)FolioItem::whereHas('folio',fn($q)=>$q->where('property_id',$propertyId))->where('type','charge')->where('department','room')->whereDate('posted_at',$date)->sum('total');$restaurant=(float)PosOrder::where('property_id',$propertyId)->whereDate('closed_at',$date)->whereHas('outlet',fn($q)=>$q->where('type','restaurant'))->sum('grand_total');$bar=(float)PosOrder::where('property_id',$propertyId)->whereDate('closed_at',$date)->whereHas('outlet',fn($q)=>$q->where('type','bar'))->sum('grand_total');$other=(float)FolioItem::whereHas('folio',fn($q)=>$q->where('property_id',$propertyId))->where('type','charge')->whereNotIn('department',['room','restaurant','bar'])->whereDate('posted_at',$date)->sum('total');$payments=(float)Payment::where('property_id',$propertyId)->where('status','successful')->whereDate('paid_at',$date)->where('method','!=','room_charge')->sum('amount');$outstanding=(float)Folio::where('property_id',$propertyId)->where('balance','>',0)->sum('balance');$audit->update(['status'=>'completed','room_revenue'=>$roomRevenue,'restaurant_revenue'=>$restaurant,'bar_revenue'=>$bar,'other_revenue'=>$other,'payments_total'=>$payments,'outstanding_folios'=>$outstanding,'occupied_rooms'=>Room::where('property_id',$propertyId)->where('status','occupied')->count(),'available_rooms'=>Room::where('property_id',$propertyId)->where('status','available')->count(),'arrivals'=>Reservation::where('property_id',$propertyId)->whereDate('check_in_at',$date)->count(),'departures'=>Reservation::where('property_id',$propertyId)->whereDate('check_out_at',$date)->count(),'exceptions'=>$exceptions,'completed_at'=>now()]);$bd->update(['status'=>'closed','closed_at'=>now(),'closed_by'=>$userId]);$next=\Carbon\Carbon::parse($date)->addDay()->toDateString();HotelBusinessDate::firstOrCreate(['property_id'=>$propertyId,'business_date'=>$next],['status'=>'open','opened_at'=>now()]);return $audit->fresh();});}
}
